const sc = (n: string) => `${base}/scenes/${n}`;
/** srcset helper for the full-scene illustrations */
const scene = (n: string, full: number) => ({
  src: sc(`${n}-1280.webp`),
  srcSet: `${sc(`${n}-640.webp`)} 640w, ${sc(`${n}-1280.webp`)} 1280w, ${sc(`${n}.webp`)} ${full}w`,
});
export const scenes = {
  recliningWide: scene("scene-reclining-wide", 2056),
  portraitWide: scene("scene-portrait-wide", 2056),
  standingTall: { src: sc("scene-standing-tall-640.webp"), srcSet: `${sc("scene-standing-tall-640.webp")} 640w, ${sc("scene-standing-tall.webp")} 1024w` },
  recliningSquare: { src: sc("scene-reclining-square-640.webp"), srcSet: `${sc("scene-reclining-square-640.webp")} 640w, ${sc("scene-reclining-square.webp")} 1254w` },
} as const;

